class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int cols = strs[0].size();
        vector<int> dp(cols, 1);
        int max_len = 1;
        for (int i = 0; i < cols; ++i) {
            for (int j = 0; j < i; ++j) {
                bool ok = true;
                for (const auto& s : strs) {
                    if (s[j] > s[i]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) dp[i] = max(dp[i], dp[j] + 1);
            }
            max_len = max(max_len, dp[i]);
        }
        return cols - max_len;
    }
};

class Solution {
    public int minDeletionSize(String[] strs) {
        int cols = strs[0].length();
        int[] dp = new int[cols];
        Arrays.fill(dp, 1);
        int maxLen = 1;
        for (int i = 0; i < cols; i++) {
            for (int j = 0; j < i; j++) {
                boolean ok = true;
                for (String s : strs) {
                    if (s.charAt(j) > s.charAt(i)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) dp[i] = Math.max(dp[i], dp[j] + 1);
            }
            maxLen = Math.max(maxLen, dp[i]);
        }
        return cols - maxLen;
    }
}

var minDeletionSize = function(strs) {
    const cols = strs[0].length;
    const dp = new Array(cols).fill(1);
    let maxLen = 1;
    for (let i = 0; i < cols; i++) {
        for (let j = 0; j < i; j++) {
            let ok = true;
            for (const s of strs) {
                if (s[j] > s[i]) {
                    ok = false;
                    break;
                }
            }
            if (ok) dp[i] = Math.max(dp[i], dp[j] + 1);
        }
        maxLen = Math.max(maxLen, dp[i]);
